// Natively drawn figures: Fig. 1.1 (four converging shifts) and Fig. 2.1 (the spatial-intelligence loop),
// both SVG generated by pipeline/webfigs.py. Hover or focus a module for its reading; the figures run on a
// single clock that pauses while the reader is inspecting them or when they are off screen.
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
const NS = 'http://www.w3.org/2000/svg';

function clock(el, tick) {
  let on = false, last = 0, t = 0, visible = true, held = false, raf = 0;
  const loop = now => {
    if (on) { t += Math.min(now - last, 64); tick(t); }
    last = now; raf = requestAnimationFrame(loop);
  };
  const sync = () => { on = visible && !held && !reduce; };
  new IntersectionObserver(es => { visible = es[0].isIntersecting; sync(); }).observe(el);
  raf = requestAnimationFrame(t0 => { last = t0; loop(t0); });
  return { hold(v) { held = v; sync(); }, get t() { return t; } };
}

// info card: floating over the figure, or written into an external panel (home page)
function infoCard(el, info, panel) {
  const card = $('.nf-card', el);
  const html = k => {
    const d = info[k]; if (!d) return '';
    return `<div class="nfc-t">${d.t}</div><p>${d.b}</p>${d.u ? `<a class="nfc-go" href="${d.u}">${d.l} →</a>` : ''}`;
  };
  // place: optional {box, top} — put the card inside `box` (a dimmed region) level with `top`
  const show = (k, g, place) => {
    if (!info[k]) return;
    if (panel) { panel.innerHTML = html(k); panel.dataset.k = k; return; }
    card.innerHTML = html(k); card.hidden = false;
    const r = el.getBoundingClientRect();
    card.style.width = '';
    if (place) {
      const bx = place.box.getBoundingClientRect();
      card.style.width = Math.max(240, bx.width - 12) + 'px';
      const cw = card.offsetWidth, ch = card.offsetHeight;
      card.style.left = Math.max(4, Math.min(bx.left - r.left + 6, r.width - cw - 4)) + 'px';
      card.style.top = Math.max(4, Math.min(place.top - r.top, r.height - ch - 4)) + 'px';
      return;
    }
    const b = g.getBoundingClientRect(), cw = card.offsetWidth, ch = card.offsetHeight;
    let left = b.right - r.left + 10, top = b.top - r.top;
    if (left + cw > r.width - 4) left = b.left - r.left - cw - 10;
    if (left < 4) { left = Math.max(4, Math.min(r.width - cw - 4, b.left - r.left)); top = b.bottom - r.top + 8; }
    top = Math.max(4, Math.min(top, r.height - ch - 4));
    card.style.left = left + 'px'; card.style.top = top + 'px';
  };
  const hide = () => { if (!panel) card.hidden = true; };
  // the panel keeps the height of its longest entry, so the layout around it never moves while the reader hovers
  if (panel) {
    const reserve = () => {
      const keep = panel.innerHTML;
      panel.style.minHeight = '0px';
      let h = 0;
      for (const k of Object.keys(info)) { panel.innerHTML = html(k); h = Math.max(h, panel.offsetHeight); }
      panel.innerHTML = keep;
      panel.style.minHeight = h + 'px';
    };
    let w = 0;
    new ResizeObserver(es => { const nw = Math.round(es[0].contentRect.width); if (nw !== w) { w = nw; reserve(); } }).observe(panel);
    document.fonts?.ready.then(reserve);
  }
  card?.addEventListener('pointerenter', () => el.classList.add('is-card'));
  card?.addEventListener('pointerleave', () => { el.classList.remove('is-card'); el.dispatchEvent(new Event('nf-leave')); });
  return { show, hide };
}

function focusable(groups, onFocus, onBlur) {
  for (const g of groups) {
    g.setAttribute('tabindex', '0');
    g.addEventListener('focus', () => onFocus(g));
    g.addEventListener('blur', () => onBlur(g));
    g.addEventListener('keydown', e => {
      if (e.key === 'Enter') { const a = g.closest('.nf').querySelector('.nf-card a, [data-def-panel] a'); if (a) location.href = a.getAttribute('href'); }
    });
  }
}

// polyline position at fraction f of a path element (optionally walked backwards)
const along = (p, f, back = false) => p.getPointAtLength(p.getTotalLength() * (back ? 1 - f : f));

// ================================================================ Fig. 2.1
function fig21(el, opts = {}) {
  const svg = $('svg', el), info = JSON.parse($('.nf-info', el).textContent);
  const panel = opts.panel || null, card = infoCard(el, info, panel);
  const G = k => $(`[data-k="${k}"]`, svg);
  const seg = c => $(`.${c} .shaft`, svg);
  const token = $('.token', svg);
  const S = [
    { k: 'env', d: 800 },
    { p: 's-obs', d: 900, k: 'obs' }, { k: 'perc', d: 1000 },
    { p: 's-pr', d: 500 }, { k: 'rep', d: 800 },
    { p: 's-rq', d: 450 }, { k: 'reason', d: 1000 }, { p: 's-rq', d: 450, back: true },
    { k: 'rep', d: 350 },
    { p: 's-rp', d: 450 }, { k: 'pred', d: 1400 }, { p: 's-rp', d: 450, back: true },
    { k: 'rep', d: 350 },
    { p: 's-ra', d: 500 }, { k: 'act', d: 900 },
    { p: 's-act', d: 900, k: 'actions' },
  ];
  const total = S.reduce((a, s) => a + s.d, 0);
  let liveK = null;
  const setLive = k => {
    if (k === liveK) return;
    if (liveK) G(liveK)?.classList.remove('is-live');
    if (k) G(k)?.classList.add('is-live');
    liveK = k;
  };
  const clk = clock(el, t => {
    let x = t % total, i = 0;
    while (x > S[i].d) { x -= S[i].d; i++; }
    const s = S[i], f = x / s.d;
    if (s.p) {
      const pt = along(seg(s.p), f, s.back);
      token.setAttribute('cx', pt.x); token.setAttribute('cy', pt.y);
      token.classList.add('on');
      setLive(s.k || null);
    } else {
      token.classList.remove('on');
      setLive(s.k);
    }
  });
  if (reduce) setLive(null);

  // focus: hovered module (or representation cell) lifted, the rest dimmed, loop paused
  const keys = ['env', 'obs', 'task', 'perc', 'act', 'rep', 'reason', 'pred', 'actions'];
  const cells = ['geometric', 'topological', 'symbolic', 'abstract'];
  let pinned = null;
  const focus = (k, g) => {
    el.classList.add('is-focus');
    $$('[data-k].is-on', svg).forEach(n => n.classList.remove('is-on'));
    g.classList.add('is-on');
    if (cells.includes(k)) { G('rep').classList.add('is-on'); el.classList.add('is-cell'); } else el.classList.remove('is-cell');
    clk.hold(true);
    card.show(k, g);
  };
  const unfocus = () => {
    if (pinned || el.classList.contains('is-card')) return;
    el.classList.remove('is-focus', 'is-cell');
    $$('[data-k].is-on', svg).forEach(n => n.classList.remove('is-on'));
    clk.hold(false);
    card.hide();
    if (panel && opts.idle) card.show(opts.idle, G(opts.idle));
  };
  const target = e => {
    const c = e.target.closest('.cell[data-k]');
    if (c) return c;
    const g = e.target.closest('[data-k]');
    return g && keys.includes(g.dataset.k) ? g : null;
  };
  svg.addEventListener('pointerover', e => { const g = target(e); if (g && !pinned) focus(g.dataset.k, g); });
  svg.addEventListener('pointerleave', () => setTimeout(unfocus, 60));
  el.addEventListener('nf-leave', unfocus);
  svg.addEventListener('click', e => {
    const g = target(e);
    if (!g) { pinned = null; unfocus(); return; }
    pinned = pinned === g ? null : g;
    focus(g.dataset.k, g);
  });
  document.addEventListener('click', e => { if (pinned && !el.contains(e.target)) { pinned = null; unfocus(); } });
  focusable([...keys.map(G), ...cells.map(G)].filter(Boolean), g => focus(g.dataset.k, g), () => unfocus());
  if (panel && opts.idle) card.show(opts.idle, G(opts.idle));
}

// ================================================================ Fig. 1.1
function fig11(el) {
  const svg = $('svg', el), info = JSON.parse($('.nf-info', el).textContent), card = infoCard(el, info);
  const rows = $$('.row', svg), hub = $('[data-k="hub"]', svg), layer = $('.pulses', svg);
  const dot = (cls, r = 1.7) => { const c = document.createElementNS(NS, 'circle'); c.setAttribute('r', r); c.setAttribute('class', cls); layer.append(c); return c; };
  // each row sends a pulse from the old state to the new one and on into spatial intelligence
  const P = 4200, lane = rows.map((r, i) => ({ f1: $('.f1 .shaft', r), f2: $('.f2 .shaft', r), d: dot('pulse'), off: i * 380 }));
  const feeds = $$('.feed', svg).map((p, i) => ({ p, d: dot('pulse sm', 1.2), off: i * 420 }));
  const conv = $$('.conv', svg).map((p, i) => ({ p, d: dot('pulse sm', 1.2), off: (i % 3) * 300 + (i > 2 ? 150 : 0) }));
  let hubOn = 0;
  const place = (d, pt, on) => { d.setAttribute('cx', pt.x); d.setAttribute('cy', pt.y); d.classList.toggle('on', on); };
  const clk = clock(el, t => {
    let arrived = false;
    for (const l of lane) {
      const x = (t - l.off + P) % P;
      if (x < 700) place(l.d, along(l.f1, x / 700), true);
      else if (x < 1000) place(l.d, along(l.f1, 1), false);
      else if (x < 1700) place(l.d, along(l.f2, (x - 1000) / 700), true);
      else { place(l.d, along(l.f2, 1), false); if (x < 2300) arrived = true; }
    }
    if (arrived !== !!hubOn) { hub.classList.toggle('is-live', arrived); hubOn = arrived ? 1 : 0; }
    for (const f of feeds) { const x = ((t - f.off) % 1800 + 1800) % 1800; place(f.d, along(f.p, Math.min(1, x / 1200)), x < 1200); }
    for (const c of conv) { const x = ((t - c.off) % 2000 + 2000) % 2000; place(c.d, along(c.p, Math.min(1, x / 1300)), x < 1300); }
  });

  let pinned = null;
  const focus = g => {
    el.classList.add('is-focus');
    $$('.is-on', svg).forEach(n => n.classList.remove('is-on'));
    g.classList.add('is-on');
    clk.hold(true);
    // a row's reading goes over the (dimmed) hub, level with the row; the hub's reading goes beside it
    card.show(g.dataset.k, g, g === hub ? null : { box: hub, top: g.getBoundingClientRect().top });
  };
  const unfocus = () => {
    if (pinned || el.classList.contains('is-card')) return;
    el.classList.remove('is-focus');
    $$('.is-on', svg).forEach(n => n.classList.remove('is-on'));
    clk.hold(false);
    card.hide();
  };
  const target = e => e.target.closest('.row, [data-k="hub"]');
  svg.addEventListener('pointerover', e => { const g = target(e); if (g && !pinned) focus(g); });
  svg.addEventListener('pointerleave', () => setTimeout(unfocus, 60));
  el.addEventListener('nf-leave', unfocus);
  svg.addEventListener('click', e => { const g = target(e); if (!g) { pinned = null; unfocus(); return; } pinned = pinned === g ? null : g; focus(g); });
  document.addEventListener('click', e => { if (pinned && !el.contains(e.target)) { pinned = null; unfocus(); } });
  focusable([...rows, hub], focus, unfocus);
}

export function mountNative(root = document, opts = {}) {
  for (const el of $$('.nf[data-nf]', root)) {
    if (el.dataset.ready) continue;
    el.dataset.ready = '1';
    if (el.dataset.nf === '21') fig21(el, opts);
    if (el.dataset.nf === '11') fig11(el);
  }
}
